changeSet.sql:
CREATE TABLE kabipay_ops.organization ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL CHECK (BTRIM(name) <> ''), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','SUSPENDED','ARCHIVED')), version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() ); CREATE TABLE kabipay_ops.principal ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), display_name VARCHAR(255) NOT NULL CHECK (BTRIM(display_name) <> ''), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')), identity_version BIGINT NOT NULL DEFAULT 1 CHECK (identity_version > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() ); CREATE TABLE kabipay_ops.principal_login_link ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), principal_id UUID NOT NULL REFERENCES kabipay_ops.principal(id), source_tenant_id UUID NOT NULL REFERENCES kabipay_ops.tenant(id), source_user_id UUID NOT NULL, issuer VARCHAR(255) NOT NULL CHECK (issuer = BTRIM(issuer) AND issuer <> ''), status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','VERIFIED','REVOKED')), verified_at TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_principal_source_login UNIQUE (source_tenant_id, source_user_id, issuer), CONSTRAINT chk_principal_verified_login CHECK (status <> 'VERIFIED' OR verified_at IS NOT NULL) ); CREATE INDEX idx_principal_login_person ON kabipay_ops.principal_login_link(principal_id, status);
CREATE TABLE kabipay_ops.organization_company ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES kabipay_ops.organization(id), tenant_id UUID NOT NULL REFERENCES kabipay_ops.tenant(id), status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACTIVE','SUSPENDED','DETACHING','DETACHED')), effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_organization_company_org_id UNIQUE (organization_id, id), CONSTRAINT uq_organization_company_provenance UNIQUE (organization_id, id, tenant_id), CONSTRAINT chk_organization_company_period CHECK (effective_to IS NULL OR effective_to > effective_from), CONSTRAINT chk_detached_company_end CHECK (status <> 'DETACHED' OR effective_to IS NOT NULL) ); -- Suspended/detaching memberships retain ownership until the detach protocol completes. CREATE UNIQUE INDEX uq_company_occupied_organization ON kabipay_ops.organization_company(tenant_id) WHERE status IN ('ACTIVE','SUSPENDED','DETACHING'); CREATE UNIQUE INDEX uq_company_pending_invitation ON kabipay_ops.organization_company(organization_id, tenant_id) WHERE status = 'PENDING';
CREATE TABLE kabipay_ops.employment_ref ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL, organization_company_id UUID NOT NULL, source_tenant_id UUID NOT NULL, source_employee_id UUID NOT NULL, principal_id UUID REFERENCES kabipay_ops.principal(id), display_name VARCHAR(255) NOT NULL CHECK (BTRIM(display_name) <> ''), employment_status VARCHAR(20) NOT NULL CHECK (employment_status IN ('ACTIVE','PROBATION','ON_LEAVE','INACTIVE','SUSPENDED','TERMINATED')), source_version BIGINT NOT NULL CHECK (source_version > 0), synced_at TIMESTAMPTZ NOT NULL, CONSTRAINT uq_employment_company_employee UNIQUE (organization_company_id, source_employee_id), CONSTRAINT fk_employment_company_provenance FOREIGN KEY (organization_id, organization_company_id, source_tenant_id) REFERENCES kabipay_ops.organization_company(organization_id, id, tenant_id) ); CREATE INDEX idx_employment_principal ON kabipay_ops.employment_ref(principal_id, employment_status);
CREATE TABLE kabipay_ops.organization_role ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES kabipay_ops.organization(id), name VARCHAR(100) NOT NULL CHECK (name = BTRIM(name) AND name <> ''), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','ARCHIVED')), version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_organization_role_org_id UNIQUE (organization_id, id) ); CREATE UNIQUE INDEX uq_organization_role_name ON kabipay_ops.organization_role(organization_id, LOWER(name)); CREATE TABLE kabipay_ops.organization_role_capability ( organization_id UUID NOT NULL, role_id UUID NOT NULL, capability_code VARCHAR(100) NOT NULL CHECK (capability_code ~ '^[a-z][a-z0-9_-]*:[a-z][a-z0-9_-]*$'), employee_scope VARCHAR(20) NOT NULL CHECK (employee_scope IN ('SELF','TEAM','DEPARTMENT','ALL')), field_policy_ref UUID, PRIMARY KEY (organization_id, role_id, capability_code), CONSTRAINT fk_role_capability_same_org FOREIGN KEY (organization_id, role_id) REFERENCES kabipay_ops.organization_role(organization_id, id) ); CREATE TABLE kabipay_ops.principal_role_binding ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES kabipay_ops.organization(id), principal_id UUID NOT NULL REFERENCES kabipay_ops.principal(id), role_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','ACTIVE','SUSPENDED','REVOKED')), effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0), granted_by UUID REFERENCES kabipay_ops.principal(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_role_binding_org_id UNIQUE (organization_id, id), CONSTRAINT fk_role_binding_same_org FOREIGN KEY (organization_id, role_id) REFERENCES kabipay_ops.organization_role(organization_id, id), CONSTRAINT chk_role_binding_period CHECK (effective_to IS NULL OR effective_to > effective_from) ); CREATE INDEX idx_role_binding_principal ON kabipay_ops.principal_role_binding(principal_id, organization_id, status); CREATE TABLE kabipay_ops.role_binding_company ( organization_id UUID NOT NULL, binding_id UUID NOT NULL, organization_company_id UUID NOT NULL, expected_grant_version BIGINT NOT NULL DEFAULT 1 CHECK (expected_grant_version > 0), activation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (activation_status IN ('PENDING','ACTIVE','REVOKED')), PRIMARY KEY (organization_id, binding_id, organization_company_id), CONSTRAINT fk_binding_company_same_org FOREIGN KEY (organization_id, binding_id) REFERENCES kabipay_ops.principal_role_binding(organization_id, id), CONSTRAINT fk_binding_membership_same_org FOREIGN KEY (organization_id, organization_company_id) REFERENCES kabipay_ops.organization_company(organization_id, id) ); -- No HR, payroll, tenant-membership or verified-identity data is seeded here. -- Status/version changes and identity evidence require the future trusted service API.

rollback.sql:
DROP TABLE kabipay_ops.role_binding_company;
DROP TABLE kabipay_ops.principal_role_binding;
DROP TABLE kabipay_ops.organization_role_capability;
DROP TABLE kabipay_ops.organization_role;
DROP TABLE kabipay_ops.employment_ref;
DROP TABLE kabipay_ops.organization_company;
DROP TABLE kabipay_ops.principal_login_link;
DROP TABLE kabipay_ops.principal;
DROP TABLE kabipay_ops.organization;
